declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    flowLow : BOOL;
    ackBtn : BOOL;
    sensorOK : BOOL;
END_VAR
VAR_OUTPUT
    alarmActive : BOOL;
    alarmAcked : BOOL;
    highHigh : BOOL;
END_VAR
VAR
    ackPrev : BOOL;
    ackEdge : BOOL;
    acknowledged : BOOL;
END_VAR

implementation:
ackEdge := ackBtn AND NOT ackPrev;
ackPrev := ackBtn;


highHigh := NOT sensorOK;


IF flowLow THEN
    IF NOT alarmActive THEN
        acknowledged := FALSE;
    END_IF
    alarmActive := TRUE;
    IF ackEdge THEN
        acknowledged := TRUE;
    END_IF
    alarmAcked := acknowledged;
ELSIF alarmActive THEN
    IF acknowledged OR ackEdge THEN
        alarmActive := FALSE;
        alarmAcked := FALSE;
        acknowledged := FALSE;
    ELSE
        alarmAcked := TRUE;
    END_IF
ELSE
    alarmAcked := FALSE;
    acknowledged := FALSE;
END_IF
